<?php
require __DIR__.'/config.php';
if(defined('RESULT_KEY')&&RESULT_KEY!==''&&!hash_equals((string)RESULT_KEY,(string)($_GET['k']??''))){http_response_code(404);exit;}
header('Content-Type: text/html; charset=utf-8');header('X-Robots-Tag: noindex, nofollow, noarchive');
try{$db=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){die('<meta charset=utf-8><body style="background:#000;color:#fff;font-family:Tahoma;text-align:center;padding:40px">تعذر الاتصال بقاعدة البيانات — تأكد من config.php</body>');}
function one($s){global $db;try{return $db->query($s)->fetch(PDO::FETCH_NUM)[0];}catch(Throwable $e){return 0;}}
function all($s){global $db;try{return $db->query($s)->fetchAll();}catch(Throwable $e){return [];}}
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
$st=[['المستخدمون','SELECT COUNT(*) FROM fs_users'],['متصلون الآن (5 د)','SELECT COUNT(*) FROM fs_users WHERE seen>NOW()-INTERVAL 5 MINUTE'],['مستخدمون جدد اليوم','SELECT COUNT(*) FROM fs_users WHERE created>CURDATE()'],['إجمالي الألعاب','SELECT COUNT(*) FROM fs_games'],['ألعاب اليوم','SELECT COUNT(*) FROM fs_games WHERE ts>CURDATE()'],['اللاعبون في الألعاب','SELECT COALESCE(SUM(players),0) FROM fs_games'],['الغرف المنشأة','SELECT COUNT(*) FROM fs_log WHERE type="room_new"'],['غرف نشطة الآن','SELECT COUNT(*) FROM fs_rooms WHERE status<>"end" AND upd>NOW()-INTERVAL 1 HOUR'],['فوز المافيا','SELECT COUNT(*) FROM fs_games WHERE winner="mafia"'],['فوز المواطنين','SELECT COUNT(*) FROM fs_games WHERE winner="citizens"'],['متوسط الجولات','SELECT ROUND(COALESCE(AVG(rounds),0),1) FROM fs_games'],['رسائل الشات','SELECT COUNT(*) FROM fs_chat'],['زيارات الموقع','SELECT COUNT(*) FROM fs_log WHERE type="visit"']];
$modes=all('SELECT mode,COUNT(*) c FROM fs_games GROUP BY mode');
$top=all('SELECT name,games,wins FROM fs_users WHERE games>0 ORDER BY wins DESC,games DESC LIMIT 10');
$gm=all('SELECT mode,players,winner,rounds,ts FROM fs_games ORDER BY id DESC LIMIT 15');
$lg=all('SELECT ts,type,room,info FROM fs_log ORDER BY id DESC LIMIT 40');
$rm=all('SELECT r.code,r.status,r.phase,r.round,r.upd,(SELECT COUNT(*) FROM fs_players p WHERE p.room=r.code) n FROM fs_rooms r ORDER BY r.upd DESC LIMIT 10');
$mn=['solo'=>'فردي','local'=>'جهاز واحد','online'=>'أونلاين'];$wn=['mafia'=>'المافيا','citizens'=>'المواطنون'];
?><!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="20"><title>النتائج والإحصائيات</title>
<style>*{box-sizing:border-box;font-family:Tahoma,sans-serif}body{margin:0;background:#07070c;color:#fff;padding:16px;max-width:980px;margin:auto}h1{text-align:center;text-shadow:0 0 18px #fff6}h2{margin:26px 0 10px;font-size:20px;border-inline-start:4px solid #4cff00;padding-inline-start:10px}
.g{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.c{background:#15151d;border:1px solid #ffffff22;border-radius:14px;padding:14px;text-align:center;box-shadow:0 0 18px #ffffff10}.c b{display:block;font-size:30px;color:#4cff00}.c span{font-size:13px;opacity:.8}
table{width:100%;border-collapse:collapse;background:#15151d;border-radius:12px;overflow:hidden;font-size:14px}td,th{padding:8px 10px;border-bottom:1px solid #ffffff14;text-align:right}th{background:#1e1e2a}.w{overflow-x:auto}a{color:#3ee0ff}.ft{text-align:center;opacity:.55;font-size:12px;margin:30px 0 8px}</style></head><body>
<h1>النتائج والإحصائيات</h1><div style="text-align:center;opacity:.7">تحديث تلقائي كل 20 ثانية</div>
<h2>نظرة عامة</h2><div class="g"><?php foreach($st as $s)echo '<div class="c"><b>'.h(one($s[1])).'</b><span>'.h($s[0]).'</span></div>';foreach($modes as $m)echo '<div class="c"><b>'.h($m['c']).'</b><span>ألعاب '.h($mn[$m['mode']]??$m['mode']).'</span></div>';?></div>
<h2>أفضل اللاعبين</h2><div class="w"><table><tr><th>#</th><th>الاسم</th><th>الألعاب</th><th>الفوز</th></tr><?php foreach($top as $i=>$t)echo '<tr><td>'.($i+1).'</td><td>'.h($t['name']?:'—').'</td><td>'.h($t['games']).'</td><td>'.h($t['wins']).'</td></tr>';?></table></div>
<h2>الغرف</h2><div class="w"><table><tr><th>الكود</th><th>الحالة</th><th>المرحلة</th><th>الجولة</th><th>اللاعبون</th><th>آخر نشاط</th></tr><?php foreach($rm as $r)echo '<tr><td>'.h($r['code']).'</td><td>'.h($r['status']).'</td><td>'.h($r['phase']).'</td><td>'.h($r['round']).'</td><td>'.h($r['n']).'</td><td>'.h($r['upd']).'</td></tr>';?></table></div>
<h2>آخر الألعاب</h2><div class="w"><table><tr><th>الوقت</th><th>النظام</th><th>اللاعبون</th><th>الفائز</th><th>الجولات</th></tr><?php foreach($gm as $r)echo '<tr><td>'.h($r['ts']).'</td><td>'.h($mn[$r['mode']]??$r['mode']).'</td><td>'.h($r['players']).'</td><td>'.h($wn[$r['winner']]??$r['winner']).'</td><td>'.h($r['rounds']).'</td></tr>';?></table></div>
<h2>سجل الأحداث (Log)</h2><div class="w"><table><tr><th>الوقت</th><th>النوع</th><th>الغرفة</th><th>تفاصيل</th></tr><?php foreach($lg as $r)echo '<tr><td>'.h($r['ts']).'</td><td>'.h($r['type']).'</td><td>'.h($r['room']).'</td><td>'.h($r['info']).'</td></tr>';?></table></div>
<div class="ft">تم التصميم من قبل Fazber Studio</div></body></html>
